"""Demo: the mod-9 obstruction for sums of three cubes (Thm 4.1 + Cor 3.2)."""
from __future__ import annotations


def nth_power_residues(n: int, m: int) -> set[int]:
    return {pow(x, n, m) for x in range(m)}


def residue_sums(n: int, s: int, m: int) -> set[int]:
    powers = nth_power_residues(n, m)
    reachable: set[int] = {0}
    for _ in range(s):
        reachable = {(r + p) % m for r in reachable for p in powers}
    return reachable


def is_sum_of_three_cubes_possible(k: int) -> bool:
    """A necessary local test: k must be a sum of three cubes modulo 9."""
    return (k % 9) in residue_sums(3, 3, 9)


if __name__ == "__main__":
    print("cubes mod 9          :", sorted(nth_power_residues(3, 9)))
    print("sums of 3 cubes mod 9:", sorted(residue_sums(3, 3, 9)))
    for k in [4, 5, 33, 42]:
        print(f"k={k}: locally possible? {is_sum_of_three_cubes_possible(k)}")

"""Demo: divisibility descent of local admissibility (Theorem 3.3)."""
from __future__ import annotations


def residue_sums(n: int, s: int, m: int) -> set[int]:
    powers = {pow(x, n, m) for x in range(m)}
    reachable: set[int] = {0}
    for _ in range(s):
        reachable = {(r + p) % m for r in reachable for p in powers}
    return reachable


def locally_admissible(n: int, s: int, k: int, m: int) -> bool:
    return (k % m) in residue_sums(n, s, m)


def verify_descent(n: int, s: int, M: int) -> bool:
    """For m | M, Adm mod M implies Adm mod m, for every k in 0..M-1."""
    divisors = [m for m in range(1, M + 1) if M % m == 0]
    for k in range(M):
        if locally_admissible(n, s, k, M):
            if not all(locally_admissible(n, s, k, m) for m in divisors):
                return False
    return True


if __name__ == "__main__":
    print("descent n=3 s=3 M=27 holds:", verify_descent(3, 3, 27))
    print("descent n=2 s=2 M=36 holds:", verify_descent(2, 2, 36))

"""Demo: CRT composition of universal surjectivity (Theorem 3.6)."""
from __future__ import annotations
from math import gcd


def residue_sums(n: int, s: int, m: int) -> set[int]:
    powers = {pow(x, n, m) for x in range(m)}
    reachable: set[int] = {0}
    for _ in range(s):
        reachable = {(r + p) % m for r in reachable for p in powers}
    return reachable


def universally_surjective(n: int, s: int, m: int) -> bool:
    return residue_sums(n, s, m) == set(range(m))


def crt_pair(a1: int, m1: int, a2: int, m2: int) -> int:
    inv = pow(m1, -1, m2)
    t = ((a2 - a1) * inv) % m2
    return (a1 + m1 * t) % (m1 * m2)


if __name__ == "__main__":
    m1, m2 = 5, 13
    assert gcd(m1, m2) == 1
    print("Surj(5):", universally_surjective(2, 2, m1))
    print("Surj(13):", universally_surjective(2, 2, m2))
    print("Surj(65):", universally_surjective(2, 2, m1 * m2))
    print("CRT glue (2 mod 5, 8 mod 13) =", crt_pair(2, m1, 8, m2))

