"""Certified decision procedure: residue-sum set R_{n,s}(m) (Theorem 4.1)."""
from __future__ import annotations
from itertools import product


def residue_sums(n: int, s: int, m: int) -> set[int]:
    """Efficient O(s*m*|P|) iterated Minkowski sum of n-th power residues."""
    powers = {pow(x, n, m) for x in range(m)}
    reachable: set[int] = {0}
    for _ in range(s):
        reachable = {(r + p) % m for r in reachable for p in powers}
    return reachable


def residue_sums_bruteforce(n: int, s: int, m: int) -> set[int]:
    """Literal Definition 2.5: O(m^s) enumeration over all s-tuples."""
    return {sum(pow(x, n, m) for x in tup) % m
            for tup in product(range(m), repeat=s)}


def locally_admissible(n: int, s: int, k: int, m: int) -> bool:
    return (k % m) in residue_sums(n, s, m)


if __name__ == "__main__":
    for n, s, m in [(2, 2, 8), (3, 3, 9), (4, 4, 16)]:
        assert residue_sums(n, s, m) == residue_sums_bruteforce(n, s, m)
        print(f"n={n} s={s} m={m}: |R|={len(residue_sums(n,s,m))}/{m}  (verified)")

"""Search for local obstructions, reduced to prime powers (Thm 3.3 + 3.6)."""
from __future__ import annotations


def residue_sums(n: int, s: int, m: int) -> set[int]:
    powers = {pow(x, n, m) for x in range(m)}
    reachable: set[int] = {0}
    for _ in range(s):
        reachable = {(r + p) % m for r in reachable for p in powers}
    return reachable


def prime_powers_up_to(bound: int) -> list[int]:
    out: list[int] = []
    for p in range(2, bound + 1):
        if all(p % q for q in range(2, int(p ** 0.5) + 1)):
            pe = p
            while pe <= bound:
                out.append(pe)
                pe *= p
    return out


def find_obstructions(n: int, s: int, bound: int = 64) -> list[tuple[int, list[int]]]:
    """Return (prime power, missing residues) for each obstructing prime power."""
    obstructions: list[tuple[int, list[int]]] = []
    for m in prime_powers_up_to(bound):
        reached = residue_sums(n, s, m)
        missing = sorted(set(range(m)) - reached)
        if missing:
            obstructions.append((m, missing))
    return obstructions


if __name__ == "__main__":
    print("three cubes obstructions:", find_obstructions(3, 3))
    print("two squares obstructions:", find_obstructions(2, 2))
    print("four 4th powers obstructions:", find_obstructions(4, 4))
